const sdl = fs.readFileSync(CLONE + '/benchmark/github-schema.graphql', 'utf8');

function bench(g, label, queryText, iters) {
  const schema = g.buildSchema(sdl, { assumeValid: true });
  const doc = g.parse(queryText);
  for (let i = 0; i < 5; i++) g.validate(schema, doc, [g.OverlappingFieldsCanBeMergedRule]);
  const t0 = process.hrtime.bigint();
  for (let i = 0; i < iters; i++) g.validate(schema, doc, [g.OverlappingFieldsCanBeMergedRule]);
  const t1 = process.hrtime.bigint();
  return Number(t1 - t0) / 1e6 / iters;
}

