// A Relay-ish query: many fragments on the same type, each selecting id/__typename and a few fields.
const relayish =
  '{ viewer { ' +
  Array.from({ length: 60 }, (_, i) => `...F${i}`).join(' ') +
  ' } }\n' +
  Array.from(
    { length: 60 },
    (_, i) => `fragment F${i} on User { id __typename login name url avatarUrl }`,
  ).join('\n');

for (const [name, q] of [['introspection', introspection], ['relayish', relayish]]) {
