  const doc = g.parse(queryText);
  for (let i = 0; i < 5; i++) g.validate(schema, doc, [g.OverlappingFieldsCanBeMergedRule]);
  const t0 = process.hrtime.bigint();
  for (let i = 0; i < iters; i++) g.validate(schema, doc, [g.OverlappingFieldsCanBeMergedRule]);
  const t1 = process.hrtime.bigint();
  return Number(t1 - t0) / 1e6 / iters;
}

const introspection = headG.getIntrospectionQuery();
// A Relay-ish query: many fragments on the same type, each selecting id/__typename and a few fields.
const relayish =
  '{ viewer { ' +
  Array.from({ length: 60 }, (_, i) => `...F${i}`).join(' ') +
  ' } }\n' +
  Array.from(
    { length: 60 },
    (_, i) => `fragment F${i} on User { id __typename login name url avatarUrl }`,
  ).join('\n');

for (const [name, q] of [['introspection', introspection], ['relayish', relayish]]) {
  const b = bench(baseG, 'base', q, 50);
  const h = bench(headG, 'head', q, 50);
  console.log(`${name}: base ${b.toFixed(2)}ms/op, head ${h.toFixed(2)}ms/op, ratio ${(h / b).toFixed(2)}x`);
}

